NEW = 'from __future__ import annotations\n\nimport asyncio\nimport inspect\nimport json\nimport os\nimport signal\nimport sys\nimport time\nfrom dataclasses import replace\nfrom pathlib import Path\nfrom typing import Any, Mapping\nfrom urllib.parse import parse_qs, urlsplit\n\nfrom .adapters.ollama import OllamaCandidateAdapter\nfrom .evidence.deterministic import verify_response\nfrom .interfaces.ingress import InputKind\nfrom .neural.server import NeuralHandler\nfrom .operations.model_takeover import verify_private_model_containment\nfrom .operations.package_identity import verify_package_manifest\nfrom .runtime import Eira2Runtime, default_config\n\n\ndef _atomic_json(path: Path, payload: Mapping[str, object]) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_name(path.name + ".new")\n    temporary.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\\n", encoding="utf-8")\n    os.chmod(temporary, 0o600)\n    os.replace(temporary, path)\n\n\ndef _verified_live_identity(root: Path, manifest: Path) -> tuple[str, str]:\n    payload = verify_package_manifest(root, manifest)\n    target = str(payload.get("source_commit_sha") or "").strip().casefold()\n    tree = str(payload.get("package_tree_sha256") or "").strip().casefold()\n    if not target or not tree:\n        raise RuntimeError("live_eira2_package_identity_invalid")\n    return target, tree\n\n\ndef live_config(root: Path, manifest: Path, *, host: str = "0.0.0.0", port: int = 8782) -> Any:\n    root = root.expanduser().resolve()\n    manifest = manifest.expanduser().resolve()\n    target, _tree = _verified_live_identity(root, manifest)\n    return replace(\n        default_config(root),\n        shadow_mode=False,\n        terminal_enabled=True,\n        voice_enabled=True,\n        repair_enabled=True,\n        self_evolution_enabled=True,\n        neural_ui_enabled=True,\n        neural_ui_host=host,\n        neural_ui_port=port,\n        package_manifest_path=manifest,\n        expected_eira2_sha=target,\n    )\n\n\ndef _install_conversation_post_bridge(runtime: Eira2Runtime, loop: asyncio.AbstractEventLoop, turn_lock: asyncio.Lock) -> None:\n    async def process_input(text: str, kind: InputKind):\n        clean = " ".join(str(text or "").split())\n        if not clean:\n            raise ValueError("empty_input")\n        async with turn_lock:\n            return await runtime.process(clean, kind=kind)\n\n    def send_json(handler: NeuralHandler, status: int, payload: Mapping[str, object]) -> None:\n        raw = (json.dumps(dict(payload), sort_keys=True) + "\\n").encode("utf-8")\n        handler.send_response(status)\n        handler.send_header("Content-Type", "application/json; charset=utf-8")\n        handler.send_header("Content-Length", str(len(raw)))\n        handler.send_header("Cache-Control", "no-store")\n        handler.send_header("Access-Control-Allow-Origin", "*")\n        handler.send_header("Access-Control-Allow-Headers", "Content-Type")\n        handler.send_header("Access-Control-Allow-Methods", "GET, HEAD, OPTIONS, POST")\n        handler.end_headers()\n        handler.wfile.write(raw)\n\n    def read_exact(handler: NeuralHandler, maximum: int) -> bytes:\n        try:\n            length = int(handler.headers.get("Content-Length") or "0")\n        except ValueError as exc:\n            raise ValueError("invalid_content_length") from exc\n        if length <= 0:\n            raise ValueError("empty_input")\n        if length > maximum:\n            raise ValueError("request_too_large")\n        raw = handler.rfile.read(length)\n        if len(raw) != length:\n            raise ValueError("short_request_body")\n        return raw\n\n    def read_json(handler: NeuralHandler) -> dict[str, object]:\n        raw = read_exact(handler, 1_000_000)\n        payload = json.loads(raw.decode("utf-8"))\n        if not isinstance(payload, dict):\n            raise ValueError("json_object_required")\n        return payload\n\n    def result_payload(result) -> dict[str, object]:\n        return {\n            "text": result.response,\n            "response": result.response,\n            "verified": bool(result.verified),\n            "correlation_id": result.correlation_id,\n        }\n\n    async def transcribe_pcm(raw: bytes, sample_rate: int, channels: int, sample_width: int) -> str:\n        fn = runtime.native_input.transcribe_pcm\n        params = inspect.signature(fn).parameters\n        kwargs: dict[str, object] = {}\n        if "sample_rate" in params:\n            kwargs["sample_rate"] = sample_rate\n        elif "rate" in params:\n            kwargs["rate"] = sample_rate\n        if "channels" in params:\n            kwargs["channels"] = channels\n        if "sample_width" in params:\n            kwargs["sample_width"] = sample_width\n        elif "sample_width_bytes" in params:\n            kwargs["sample_width_bytes"] = sample_width\n        elif "width" in params:\n            kwargs["width"] = sample_width\n        value = await fn(raw, **kwargs)\n        if isinstance(value, Mapping):\n            text = str(value.get("utterance") or value.get("text") or value.get("transcript") or "").strip()\n        else:\n            text = str(value or "").strip()\n        if not text:\n            raise RuntimeError("native_transcription_empty")\n        return text\n\n    def do_POST(handler: NeuralHandler) -> None:\n        parsed = urlsplit(handler.path)\n        path = parsed.path\n        try:\n            if path == "/v1/text":\n                payload = read_json(handler)\n                text = str(payload.get("text") or payload.get("message") or "").strip()\n                source = str(payload.get("source") or "text").casefold()\n                kind = InputKind.IPHONE_VOICE if "voice" in source else InputKind.IPHONE_TEXT\n                future = asyncio.run_coroutine_threadsafe(process_input(text, kind), loop)\n                result = future.result(timeout=300)\n                send_json(handler, 200, {"ok": True, "result": result_payload(result)})\n                return\n\n            if path == "/v1/listen":\n                query = parse_qs(parsed.query)\n                sample_rate = int((query.get("sample_rate") or ["16000"])[0])\n                channels = int((query.get("channels") or ["1"])[0])\n                sample_width = int((query.get("sample_width") or ["2"])[0])\n                if sample_rate < 8000 or sample_rate > 192000:\n                    raise ValueError("invalid_sample_rate")\n                if channels < 1 or channels > 8:\n                    raise ValueError("invalid_channels")\n                if sample_width not in {1, 2, 3, 4}:\n                    raise ValueError("invalid_sample_width")\n                raw = read_exact(handler, 32_000_000)\n                transcript_future = asyncio.run_coroutine_threadsafe(\n                    transcribe_pcm(raw, sample_rate, channels, sample_width), loop\n                )\n                utterance = transcript_future.result(timeout=180)\n                answer_future = asyncio.run_coroutine_threadsafe(\n                    process_input(utterance, InputKind.IPHONE_VOICE), loop\n                )\n                result = answer_future.result(timeout=300)\n                send_json(handler, 200, {\n                    "ok": True,\n                    "utterance": utterance,\n                    "text": utterance,\n                    "result": result_payload(result),\n                })\n                return\n\n            if path in {"/api/input", "/api/chat", "/api/conversation", "/api/message", "/api/voice"}:\n                payload = read_json(handler)\n                text = str(payload.get("text") or payload.get("message") or payload.get("transcript") or payload.get("utterance") or "").strip()\n                source = str(payload.get("source") or payload.get("kind") or "").casefold()\n                voice_hint = bool(payload.get("voice") is True or "voice" in source or payload.get("transcript") or payload.get("utterance"))\n                kind = InputKind.IPHONE_VOICE if (path == "/api/voice" or voice_hint) else InputKind.IPHONE_TEXT\n                future = asyncio.run_coroutine_threadsafe(process_input(text, kind), loop)\n                result = future.result(timeout=300)\n                send_json(handler, 200, {"ok": True, **result_payload(result), "input_kind": kind.value})\n                return\n\n            if path in {"/api/mute", "/api/listening/mute", "/api/ambient/mute"}:\n                payload = read_json(handler)\n                if "muted" in payload:\n                    muted = bool(payload["muted"])\n                else:\n                    text = str(payload.get("text") or payload.get("state") or "").casefold()\n                    muted = not ("unmute" in text or "false" in text or "resume" in text)\n                future = asyncio.run_coroutine_threadsafe(runtime.senses.set_ambient_muted(muted), loop)\n                send_json(handler, 200, future.result(timeout=30))\n                return\n\n            send_json(handler, 404, {"ok": False, "error": "post_route_not_found"})\n        except ValueError as exc:\n            send_json(handler, 400, {"ok": False, "error": str(exc)[:1200]})\n        except Exception as exc:\n            send_json(handler, 500, {"ok": False, "error": f"{type(exc).__name__}:{exc}"[:1200]})\n\n    previous_options = getattr(NeuralHandler, "do_OPTIONS", None)\n    def do_OPTIONS(handler: NeuralHandler) -> None:\n        if urlsplit(handler.path).path.startswith(("/v1/", "/api/")):\n            handler.send_response(204)\n            handler.send_header("Access-Control-Allow-Origin", "*")\n            handler.send_header("Access-Control-Allow-Headers", "Content-Type")\n            handler.send_header("Access-Control-Allow-Methods", "GET, HEAD, OPTIONS, POST")\n            handler.send_header("Content-Length", "0")\n            handler.end_headers()\n            return\n        if previous_options is not None:\n            previous_options(handler)\n            return\n        handler.send_response(204)\n        handler.send_header("Content-Length", "0")\n        handler.end_headers()\n\n    NeuralHandler.do_POST = do_POST\n    NeuralHandler.do_OPTIONS = do_OPTIONS\n\n\nasync def run_live(root: Path, manifest: Path, *, model: str = "", host: str = "0.0.0.0", port: int = 8782) -> dict[str, object]:\n    root = root.expanduser().resolve()\n    manifest = manifest.expanduser().resolve()\n    target, package_tree = _verified_live_identity(root, manifest)\n    config = live_config(root, manifest, host=host, port=port)\n    if config.expected_eira2_sha != target:\n        raise RuntimeError("live_config_identity_mismatch")\n\n    model_containment = verify_private_model_containment(runtime_root=root)\n    socket_path = str(model_containment.get("unix_socket") or "").strip()\n    if not socket_path:\n        raise RuntimeError("live_private_model_unix_socket_missing")\n    selected_model = model or os.getenv("EIRA_MODEL") or "qwen2.5:3b"\n    allowed_models = {str(value) for value in model_containment.get("required_models") or ()}\n    if selected_model not in allowed_models:\n        raise RuntimeError("live_model_not_in_attested_private_set:" + selected_model)\n\n    adapter = OllamaCandidateAdapter(model=selected_model, unix_socket=socket_path)\n    runtime = Eira2Runtime(config, generate=adapter.generate, verify=verify_response)\n    loop = asyncio.get_running_loop()\n    turn_lock = asyncio.Lock()\n    _install_conversation_post_bridge(runtime, loop, turn_lock)\n\n    await runtime.start()\n    health = await runtime.health.snapshot()\n    if health.get("required_failures"):\n        await runtime.stop()\n        raise RuntimeError("live_required_services_not_healthy")\n\n    stop_event = asyncio.Event()\n    for signum in (signal.SIGINT, signal.SIGTERM):\n        try:\n            loop.add_signal_handler(signum, stop_event.set)\n        except (NotImplementedError, RuntimeError):\n            pass\n\n    async def terminal_turn(text: str) -> None:\n        clean = text.strip()\n        if not clean:\n            return\n        async with turn_lock:\n            try:\n                result = await runtime.process(clean, kind=InputKind.TERMINAL)\n                print("Eira: " + result.response, flush=True)\n            except Exception as exc:\n                print(f"EIRA2_INPUT_ERROR={type(exc).__name__}:{exc}", flush=True)\n\n    terminal_reader_installed = False\n    if config.terminal_enabled and sys.stdin is not None and sys.stdin.isatty():\n        try:\n            fd = sys.stdin.fileno()\n            def on_terminal_input() -> None:\n                line = sys.stdin.readline()\n                if line == "":\n                    try:\n                        loop.remove_reader(fd)\n                    except Exception:\n                        pass\n                    return\n                loop.create_task(terminal_turn(line))\n            loop.add_reader(fd, on_terminal_input)\n            terminal_reader_installed = True\n        except (AttributeError, OSError, RuntimeError, ValueError):\n            terminal_reader_installed = False\n\n    receipt_path = root / "var" / "eira2-live-runtime.json"\n    receipt: dict[str, object] = {\n        "schema": "eira2_live_runtime_v7",\n        "ok": True,\n        "active": True,\n        "pid": os.getpid(),\n        "started_unix_ns": time.time_ns(),\n        "runtime_authority": "eira2",\n        "shadow_mode": False,\n        "git_metadata_required_at_runtime": False,\n        "target_eira2_sha": config.expected_eira2_sha,\n        "package_tree_sha256": package_tree,\n        "package_identity_verified_at_boot": True,\n        "required_services_healthy": True,\n        "model_role": "private_candidate_only",\n        "model_name": selected_model,\n        "model_transport": "unix_domain_socket",\n        "model_unix_socket": socket_path,\n        "model_store_under_eira2": model_containment.get("model_store_under_eira2") is True,\n        "model_outbound_network_allowed": False,\n        "model_private_network_verified_at_boot": True,\n        "model_direct_delivery_authority": False,\n        "model_direct_tool_authority": False,\n        "model_direct_identity_authority": False,\n        "model_direct_memory_acceptance": False,\n        "neural_ui_host": host,\n        "neural_ui_port": int(runtime.neural_ui.port if runtime.neural_ui is not None else port),\n        "voice_enabled": True,\n        "repair_enabled": True,\n        "self_evolution_enabled": True,\n        "conversation_http_post_enabled": True,\n        "conversation_http_routes": [\n            "/v1/text", "/v1/listen", "/api/input", "/api/chat",\n            "/api/conversation", "/api/message", "/api/voice"\n        ],\n        "iphone_pcm_transcription_authority": "interfaces.native.transcribe_pcm",\n        "conversation_authority": "Eira2Runtime.process",\n        "delivery_authority": "delivery.gate",\n        "voice_delivery_authority": "delivery.voice",\n        "terminal_input_enabled": terminal_reader_installed,\n        "clean_shutdown": False,\n    }\n    _atomic_json(receipt_path, receipt)\n    print(json.dumps(receipt, sort_keys=True), flush=True)\n\n    try:\n        await stop_event.wait()\n    finally:\n        if terminal_reader_installed:\n            try:\n                loop.remove_reader(sys.stdin.fileno())\n            except Exception:\n                pass\n        await runtime.stop()\n        stopped = dict(receipt)\n        stopped.update({"active": False, "stopped_unix_ns": time.time_ns(), "clean_shutdown": True})\n        _atomic_json(receipt_path, stopped)\n    return receipt\n'

def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
if not TARGET.is_file() or not MANIFEST.is_file():
    raise SystemExit('EIRA2_LIVE_CONVERSATION_V2=FAIL missing_target_or_manifest')
current = sha(TARGET)
if current != EXPECTED:
    raise SystemExit('EIRA2_LIVE_CONVERSATION_V2=FAIL unexpected_live_hash:' + current)
backup_dir = ROOT / 'eira_probe' / 'live_conversation_v2_backup' / time.strftime('%Y%m%dT%H%M%S')
backup_dir.mkdir(parents=True, exist_ok=False)
shutil.copy2(TARGET, backup_dir / 'live.py')
shutil.copy2(MANIFEST, backup_dir / 'eira2-package-manifest.json')
try:
    tmp = TARGET.with_name('live.py.new')
    tmp.write_text(NEW, encoding='utf-8')
    os.chmod(tmp, TARGET.stat().st_mode)
    py_compile.compile(str(tmp), doraise=True)
    os.replace(tmp, TARGET)
    from eira2.operations.package_identity import write_package_manifest, verify_package_manifest
    previous = json.loads((backup_dir / 'eira2-package-manifest.json').read_text(encoding='utf-8'))
    source_sha = str(previous.get('source_commit_sha') or '').strip()
    if not source_sha:
        raise RuntimeError('source_commit_sha_missing')
    write_package_manifest(ROOT, source_commit_sha=source_sha)
    verified = verify_package_manifest(ROOT, MANIFEST)
    print('EIRA2_LIVE_CONVERSATION_V2=PASS')
    print('LIVE_SHA256=' + sha(TARGET))
    print('PACKAGE_TREE_SHA256=' + str(verified.get('package_tree_sha256') or ''))
    print('ROUTES=/v1/text,/v1/listen')
    print('PCM_AUTHORITY=interfaces.native.transcribe_pcm')
    print('CONVERSATION_AUTHORITY=Eira2Runtime.process')
    print('VOICE_AUTHORITY=delivery.voice')
    print('BACKUP=' + str(backup_dir))
except Exception as exc:
    shutil.copy2(backup_dir / 'live.py', TARGET)
    shutil.copy2(backup_dir / 'eira2-package-manifest.json', MANIFEST)
    raise SystemExit('EIRA2_LIVE_CONVERSATION_V2=FAIL rolled_back:' + type(exc).__name__ + ':' + str(exc))
